import{_ as r,o as a,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"সিম্বায়োসিস শ্রম আইন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/41-共生劳动法.md","filePath":"bn/41-共生劳动法.md","lastUpdated":null}'),o={name:"bn/41-共生劳动法.md"};function e(i,t,n,s,h,_){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="সিম্বায়োসিস-শ্রম-আইন" tabindex="-1">সিম্বায়োসিস শ্রম আইন <a class="header-anchor" href="#সিম্বায়োসিস-শ্রম-আইন" aria-label="Permalink to &quot;সিম্বায়োসিস শ্রম আইন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>41</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>সিম্বায়োসিস শ্রম, বেশি পরিশ্রম বেশি লাভ, শ্রম অধিকার, যৌথ উৎপাদন চুক্তি, শোষণ বিরোধী</td></tr></tbody></table><h2 id="_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" tabindex="-1">1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি <a class="header-anchor" href="#_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" aria-label="Permalink to &quot;1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি&quot;">​</a></h2><p>《সিম্বায়োসিস শ্রম আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার আইনি ব্যবস্থায় 《সিম্বায়োসিস সংবিধান》 এর সাথে সমান্তরাল মূল আইনগুলির মধ্যে একটি, এবং এর উদ্দেশ্য হল হেঙ্গুয়ানঝৌর ভেতরে সমস্ত শ্রম এবং অবদান কার্যক্রমকে নিয়ন্ত্রণ করা, &quot;বেশি পরিশ্রম বেশি লাভ, নিজে থেকে বৃদ্ধি পাওয়া&quot; বণ্টনের ব্যবস্থা স্থাপন করা, এবং আইনি স্তর থেকে লুঠেরা শোষণের মূল নির্মূল করা।</p><p>এই আইন নিম্নলিখিত মূল নীতি স্থাপন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>শ্রমের মর্যাদা নীতি</td><td>সমস্ত বৈধ শ্রম আইন দ্বারা সুরক্ষিত, শ্রমিকের ব্যক্তিগত মর্যাদা লঙ্ঘনযোগ্য নয়</td></tr><tr><td>বেশি পরিশ্রম বেশি লাভ নীতি</td><td>শ্রমের পারিশ্রমিক অবদানের পরিমাণের সাথে সরাসরি যুক্ত, অবদান যত বেশি লাভ তত বেশি, পরিশ্রম ছাড়া লাভ নিষিদ্ধ</td></tr><tr><td>স্বেচ্ছাশ্রম নীতি</td><td>জোরপূর্বক শ্রম এবং দাসত্ব নিষিদ্ধ, শ্রমিক শ্রমের বিষয়বস্তু এবং শ্রমের পদ্ধতি স্বাধীনভাবে বেছে নেওয়ার অধিকার রাখে</td></tr><tr><td>ন্যায্য পারিশ্রমিক নীতি</td><td>সমান কাজে সমান পারিশ্রমিক, প্রজাতি, সাধনার স্তর, উত্সের ভিত্তিতে পারিশ্রমিক বৈষম্য নিষিদ্ধ</td></tr><tr><td>শ্রম নিশ্চয়তা নীতি</td><td>রাষ্ট্র এবং সভ্যতার শ্রমিকদের জন্য নিরাপদ শ্রম পরিবেশ এবং মৌলিক সামাজিক নিশ্চয়তা প্রদানের বাধ্যতা রয়েছে</td></tr><tr><td>সিম্বায়োসিস সহযোগিতা নীতি</td><td>শ্রমিকদের মধ্যে সহযোগিতা এবং পারস্পরিক সহায়তা উৎসাহিত করা, মারাত্মক প্রতিযোগিতা এবং শূন্য-যোগ খেলার বিরোধিতা করা</td></tr></tbody></table><h2 id="_2-শ্রমিকের-মৌলিক-অধিকার" tabindex="-1">2. শ্রমিকের মৌলিক অধিকার <a class="header-anchor" href="#_2-শ্রমিকের-মৌলিক-অধিকার" aria-label="Permalink to &quot;2. শ্রমিকের মৌলিক অধিকার&quot;">​</a></h2><p>সিম্বায়োসিস শ্রম আইন হেঙ্গুয়ানঝৌর ভেতরে সমস্ত শ্রম ক্ষমতা সম্পন্ন জীবকে নিম্নলিখিত অধিকার প্রদান করে:</p><ol><li><strong>সমান নিয়োগ অধিকার</strong>: কোনো জীব চাকরি খোঁজা এবং নিয়োগের প্রক্রিয়ায় প্রজাতি, সাধনার স্তর, উত্স, লিঙ্গ ইত্যাদি কারণের কারণে বৈষম্যের শিকার হয় না।</li><li><strong>স্বাধীন পেশা নির্বাচন অধিকার</strong>: শ্রমিক নিজের ইচ্ছা এবং ক্ষমতা অনুযায়ী পেশা, পদ এবং কাজের স্থান বেছে নেওয়ার অধিকার রাখে, এবং আইন অনুযায়ী পেশা পরিবর্তন করার অধিকার রাখে।</li><li><strong>যুক্তিসঙ্গত পারিশ্রমিক অধিকার</strong>: শ্রমিক তার শ্রম অবদানের সাথে মেলে পারিশ্রমিক পাওয়ার অধিকার রাখে, পারিশ্রমিক সভ্যতার নির্ধারিত সর্বনিম্ন নিশ্চয়তা মানদণ্ডের নিচে হতে পারে না।</li><li><strong>বিশ্রাম এবং ছুটির অধিকার</strong>: শ্রমিক যুক্তিসঙ্গত কাজের সময় ব্যবস্থা এবং নিয়মিত ছুটি পাওয়ার অধিকার রাখে, সীমাহীনভাবে শ্রমের সময় বাড়ানো নিষিদ্ধ।</li><li><strong>শ্রম নিরাপত্তা অধিকার</strong>: শ্রমিক নিরাপদ, স্বাস্থ্যকর পরিবেশে শ্রম করার অধিকার রাখে, নিয়োগকারীকে অবশ্যই মানদণ্ড অনুযায়ী শ্রম সুরক্ষা শর্ত প্রদান করতে হবে।</li><li><strong>পেশাদার প্রশিক্ষণ অধিকার</strong>: শ্রমিক পেশাদার দক্ষতা প্রশিক্ষণ এবং সাধনা নির্দেশনা পাওয়ার অধিকার রাখে, নিয়োগকারী এবং রাষ্ট্রের প্রশিক্ষণ সম্পদ প্রদানের বাধ্যতা রয়েছে।</li><li><strong>সংঘ গঠন এবং আলোচনা অধিকার</strong>: শ্রমিক আইন অনুযায়ী শ্রমিক সংঘ গঠন বা যোগ দেওয়ার অধিকার রাখে, এবং সম্মিলিত আলোচনার মাধ্যমে নিজের অধিকার রক্ষা করার অধিকার রাখে।</li><li><strong>অভিযোগ এবং প্রতিকার অধিকার</strong>: শ্রমিক শ্রম অধিকার লঙ্ঘিত হলে, শ্রম সালিশ প্রতিষ্ঠান এবং সিম্বায়োসিস আদালতে অভিযোগ এবং মামলা দায়ের করার অধিকার রাখে।</li></ol><h2 id="_3-যৌথ-উৎপাদন-চুক্তি-ব্যবস্থার-আইনিকরণ" tabindex="-1">3. যৌথ উৎপাদন চুক্তি ব্যবস্থার আইনিকরণ <a class="header-anchor" href="#_3-যৌথ-উৎপাদন-চুক্তি-ব্যবস্থার-আইনিকরণ" aria-label="Permalink to &quot;3. যৌথ উৎপাদন চুক্তি ব্যবস্থার আইনিকরণ&quot;">​</a></h2><p>যৌথ উৎপাদন চুক্তি ব্যবস্থা হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার সম্পদ বণ্টনের মূল ব্যবস্থা, এবং 《সিম্বায়োসিস শ্রম আইন》 এটিকে আইনি আকারে স্থির করে:</p><ul><li><strong>চুক্তির বিষয়</strong>: যেকোনো শ্রম ক্ষমতা সম্পন্ন জীব চুক্তির বিষয় হিসেবে কাজ করতে পারে, ব্যক্তি বা সমষ্টি উভয়ই চুক্তি করতে পারে।</li><li><strong>চুক্তির বিষয়বস্তু</strong>: সাধনা সম্পদ উন্নয়ন,位面 রক্ষণাবেক্ষণ, জ্ঞান বংশগতি, প্রযুক্তি গবেষণা ও উন্নয়ন, পাবলিক সেবা ইত্যাদি ক্ষেত্র অন্তর্ভুক্ত কিন্তু সীমাবদ্ধ নয়।</li><li><strong>চুক্তির মেয়াদ</strong>: চুক্তির বিষয়বস্তুর প্রকৃতি অনুযায়ী নির্ধারিত হয়, স্বল্পমেয়াদী চুক্তি এক থেকে তিন বছর, দীর্ঘমেয়াদী চুক্তি পাঁচ থেকে বিশ বছর, মেয়াদ শেষে নবায়ন করা যায়।</li><li><strong>লাভ বণ্টন</strong>: চুক্তিকারীর লাভ তার উৎপাদনের সাথে সরাসরি যুক্ত, উৎপাদনের একটি অংশ পাবলিক সঞ্চয়ে জমা দেওয়া হয়, অবশিষ্ট অংশ চুক্তিকারীর সম্পত্তি।</li><li><strong>প্রত্যাহার ব্যবস্থা</strong>: চুক্তিকারীর যুক্তিসঙ্গত মেয়াদের মধ্যে আগাম জানানোর পরে চুক্তি থেকে প্রত্যাহার করার অধিকার রাখে, এবং চুক্তি সম্পর্কে জোরপূর্বক বাঁধা যাবে না।</li><li><strong>বিবাদ সমাধান</strong>: চুক্তি বিবাদ অগ্রাধিকারে শ্রম সালিশের মাধ্যমে সমাধান করা হয়, সালিশের ফলাফলে অসন্তুষ্ট হলে সিম্বায়োসিস আদালতে মামলা দায়ের করা যায়।</li></ul><h2 id="_4-বিশেষ-শ্রম-সুরক্ষা" tabindex="-1">4. বিশেষ শ্রম সুরক্ষা <a class="header-anchor" href="#_4-বিশেষ-শ্রম-সুরক্ষা" aria-label="Permalink to &quot;4. বিশেষ শ্রম সুরক্ষা&quot;">​</a></h2><p>হেঙ্গুয়ানঝৌর ভেতরে বিভিন্ন জীব রূপের বিশেষ চাহিদা বিবেচনা করে, এই আইন বিশেষ শ্রম সুরক্ষা ব্যবস্থা স্থাপন করে:</p><table tabindex="0"><thead><tr><th>সুরক্ষার বিষয়</th><th>বিশেষ সুরক্ষা ব্যবস্থা</th></tr></thead><tbody><tr><td>প্রাথমিক সাধক</td><td>তার ক্ষমতার বাইরে উচ্চ-ঝুঁকিপূর্ণ শ্রম নির্ধারণ করা যাবে না, এবং গুরু নির্দেশনা প্রদান করতে হবে</td></tr><tr><td>গর্ভাবস্থা ও সন্তান প্রসবকারী মহিলা জীব</td><td>কমপক্ষে ছয় মাসের বেতনসহ মাতৃত্ব ছুটির অধিকার রাখে, স্তন্যপান কালীন সময়ে উচ্চ-তীব্রতার শ্রম নির্ধারণ করা যাবে না</td></tr><tr><td>প্রতিবন্ধী এবং আহত-অসুস্থ জীব</td><td>যুক্তিসঙ্গত শ্রম পদ সমন্বয় এবং অপ্রতিবন্ধী শ্রম পরিবেশ নিশ্চয়তার অধিকার রাখে</td></tr><tr><td>বিদেশী শ্রমিক</td><td>নিয়োগকারীকে অবশ্যই বিদেশীদের শারীরিক বৈশিষ্ট্য এবং সাংস্কৃতিক অভ্যাসকে সম্মান করতে হবে, এবং মানানসই শ্রম শর্ত প্রদান করতে হবে</td></tr><tr><td>উচ্চবয়স্ক শ্রমিক</td><td>নির্দিষ্ট বয়সে পৌঁছানোর পরে শ্রমের তীব্রতা কমানো বা পরামর্শদাতা পদে স্থানান্তরের জন্য আবেদন করতে পারে</td></tr></tbody></table><h2 id="_5-আইনি-দায়বদ্ধতা-এবং-বাস্তবায়ন-নিশ্চয়তা" tabindex="-1">5. আইনি দায়বদ্ধতা এবং বাস্তবায়ন নিশ্চয়তা <a class="header-anchor" href="#_5-আইনি-দায়বদ্ধতা-এবং-বাস্তবায়ন-নিশ্চয়তা" aria-label="Permalink to &quot;5. আইনি দায়বদ্ধতা এবং বাস্তবায়ন নিশ্চয়তা&quot;">​</a></h2><p>নিয়োগকারী এই আইনের বিধান লঙ্ঘন করলে, অপরাধের গুরুত্ব অনুযায়ী নিম্নলিখিত দায়বদ্ধতা গ্রহণ করবে:</p><ol><li>শ্রমিকের প্রাপ্য পারিশ্রমিক এবং ক্ষতিপূরণ প্রদান (ক্ষতিপূরণ বকেয়া পারিশ্রমিকের এক থেকে তিন গুণ)।</li><li>নির্দিষ্ট সময়ের মধ্যে সংশোধন করার নির্দেশ দেওয়া হবে, সময়মতো সংশোধন না করলে জরিমানা করা হবে।</li><li>গুরুতর অপরাধের ক্ষেত্রে, ব্যবসায়িক লাইসেন্স বাতিল করা হবে এবং সম্পর্কিত দায়বদ্ধ ব্যক্তিদের নির্দিষ্ট সময়ের জন্য পরিচালনা কাজে নিয়োজিত হতে নিষিদ্ধ করা হবে।</li><li>অপরাধ গঠন করলে, আইন অনুযায়ী ফৌজদারি দায়বদ্ধতা আরোপ করা হবে।</li></ol><p>রাষ্ট্র শ্রম তদারকি প্রতিষ্ঠান স্থাপন করে, যা নিয়োগকারীদের শ্রম আইন মেনে চলার বিষয়ে তদারকি এবং পরীক্ষা করার জন্য দায়ী। শ্রমিক সংঘ শ্রমিকদের প্রতিনিধিত্ব করে শ্রম তদারকি এবং সম্মিলিত আলোচনায় অংশগ্রহণ করার অধিকার রাখে।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《সিম্বায়োসিস শ্রম আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার &quot;বেশি পরিশ্রম বেশি লাভ&quot; দর্শনের আইনি বাহক। এটি শ্রমকে শোষণের বিষয় থেকে সম্মানিত অধিকারে রূপান্তর করেছে, এবং বণ্টনকে লুঠেরা দখল থেকে অবদানভিত্তিক প্রতিদানে রূপান্তর করেছে, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য দৃঢ় শ্রম ব্যবস্থার ভিত্তি স্থাপন করেছে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>06-多劳多得分配原理 (বেশি পরিশ্রম বেশি লাভ বণ্টনের নীতি)</li><li>22-资源分配联产承包机制 (সম্পদ বণ্টন যৌথ উৎপাদন চুক্তি ব্যবস্থা)</li><li>42-消费者保护法 (ভোক্তা সুরক্ষা আইন)</li></ul>',23)])])}const c=r(o,[["render",e]]);export{u as __pageData,c as default};
